def _losing(limit):
    # P-positions of Wythoff's game: (floor(n*phi), floor(n*phi^2)),
    # plus the mirrored pair.
    loses = set()
    n = 0
    phi = (1 + 5 ** 0.5) / 2.0
    while True:
        xi = int(n * phi)
        yi = xi + n
        if xi > limit:
            break
        if n > 0:
            loses.add((xi, yi))
            loses.add((yi, xi))
        n += 1
    return loses


def solve(text: str) -> str:
    data = text.split()
    a = int(data[0])
    b = int(data[1])
    loses = _losing(max(a, b))
    if (a, b) in loses:
        return 'LOSE'
    for i in range(0, a + 1):
        for j in range(0, b + 1):
            if i == 0 and j == 0:
                continue
            if i > 0 and j > 0 and i != j:
                continue
            if (a - i, b - j) in loses:
                return 'WIN %d %d' % (i, j)
    return 'LOSE'
